with payments_by_order as (select order_id, sum(amount) as total_amount, max(amount) - min(amount) as amount_range from payments where method = 'cash' group by order_id) select orders.id, orders.shipping_fee, payments_by_order.total_amount, payments_by_order.amount_range from orders inner join payments_by_order on orders.id = payments_by_order.order_id where payments_by_order.amount_range >= 64 order by id desc
